/**
 * ============================================================================
 * evaluate.cjs — AUTOMATED EVALUATION HARNESS
 * ============================================================================
 *
 * Produces the empirical results reported in the evaluative essay (component
 * 3). Every figure quoted in the findings chapter is generated by this script,
 * so the evaluation is reproducible: an examiner can re-run it and obtain the
 * same numbers.
 *
 * RUN WITH:   npm run evaluate
 *
 * That script first compiles src/services with the project's own TypeScript
 * compiler into .evaluation-build/, then executes this file against the
 * compiled output. No additional dependencies are installed, and the code
 * under test is the same code the application ships.
 *
 * OUTPUTS:
 *   evaluation/results/results.json  — machine-readable results
 *   evaluation/results/report.md     — formatted tables for the appendix
 *   stdout                           — human-readable summary
 *
 * TEST PROCEDURES (as specified in methodology section 3.5):
 *   T1  Route optimisation: correctness against an independent reference
 *       implementation, plus latency benchmarking.
 *   T2  Dispatch model: response of the leaky bucket to booking velocity.
 *   T3  Ticket integrity: acceptance, tamper detection, forgery rejection,
 *       avalanche behaviour, and collision resistance.
 *   T4  Concurrency: behaviour of the seat-reservation write path under
 *       simultaneous booking.
 *   T5  Degradation: behaviour when the cloud database is unavailable.
 *
 * A NOTE ON HONESTY OF REPORTING
 * ------------------------------
 * This harness reports what it measures, including where the artefact fails.
 * T4 in particular records a defect rather than a success. A test suite that
 * only confirms what the developer hoped to find is not evidence.
 */

'use strict';

const fs = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// ENVIRONMENT SETUP
// ---------------------------------------------------------------------------
// Force the offline tier before anything is imported. database.ts decides
// which storage tier to use AT MODULE LOAD, by reading process.env and testing
// for `window`, so both must be arranged before the require() below.
delete process.env.NEXT_PUBLIC_SUPABASE_URL;
delete process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

/** Minimal in-memory localStorage, sufficient for the data layer's use of it. */
class MemoryStorage {
  constructor() { this.store = new Map(); }
  getItem(k) { return this.store.has(k) ? this.store.get(k) : null; }
  setItem(k, v) { this.store.set(k, String(v)); }
  removeItem(k) { this.store.delete(k); }
  clear() { this.store.clear(); }
}

const BUILD = path.join(__dirname, '..', '.evaluation-build', 'services');
const algorithms = require(path.join(BUILD, 'algorithms.js'));

const {
  calculateShortestPath,
  runLeakyBucketSimulation,
  generateOfflineSignature,
  verifyOfflineTicket,
  TRANSIT_GRAPH_NODES,
  TRANSIT_GRAPH_EDGES
} = algorithms;

// Accumulates every result for the JSON and markdown outputs.
const results = {
  meta: {
    generatedAt: new Date().toISOString(),
    node: process.version,
    platform: `${process.platform} ${process.arch}`
  }
};
const md = [];

const say = (s = '') => { console.log(s); };
const heading = (s) => { say(''); say('='.repeat(74)); say(s); say('='.repeat(74)); };

/** Formats a number to a fixed number of decimals without trailing noise. */
const f = (n, d = 2) => Number(n).toFixed(d);

// ===========================================================================
// T1 — ROUTE OPTIMISATION: CORRECTNESS AND LATENCY
// ===========================================================================
// Dijkstra's algorithm is checked against an independently written
// Floyd-Warshall all-pairs implementation. The two algorithms share no code,
// so agreement on all node pairs is meaningful evidence of correctness rather
// than a restatement of the same logic.

function t1RoutingCorrectnessAndLatency() {
  heading('T1  ROUTE OPTIMISATION — CORRECTNESS AND LATENCY');

  const ids = TRANSIT_GRAPH_NODES.map(n => n.id);
  const n = ids.length;
  const idx = Object.fromEntries(ids.map((id, i) => [id, i]));

  // --- Independent reference: Floyd-Warshall -------------------------------
  const INF = Infinity;
  const dist = Array.from({ length: n }, (_, i) =>
    Array.from({ length: n }, (_, j) => (i === j ? 0 : INF))
  );
  for (const e of TRANSIT_GRAPH_EDGES) {
    const a = idx[e.from], b = idx[e.to];
    // The graph is undirected, so each edge relaxes both directions.
    dist[a][b] = Math.min(dist[a][b], e.distanceKm);
    dist[b][a] = Math.min(dist[b][a], e.distanceKm);
  }
  for (let k = 0; k < n; k++)
    for (let i = 0; i < n; i++)
      for (let j = 0; j < n; j++)
        if (dist[i][k] + dist[k][j] < dist[i][j]) dist[i][j] = dist[i][k] + dist[k][j];

  // --- Compare every ordered pair against the implementation ---------------
  let agree = 0, disagree = 0;
  const mismatches = [];
  const pathTable = [];

  for (const from of ids) {
    for (const to of ids) {
      if (from === to) continue;
      const got = calculateShortestPath(from, to);
      const expected = dist[idx[from]][idx[to]];
      const ok = got.totalDistance === expected;
      ok ? agree++ : disagree++;
      if (!ok) mismatches.push({ from, to, got: got.totalDistance, expected });
      pathTable.push({
        from, to,
        path: got.path.join(' -> '),
        km: got.totalDistance,
        mins: got.totalTimeMins,
        reference: expected,
        agrees: ok
      });
    }
  }

  say(`Node pairs tested                : ${agree + disagree}`);
  say(`Agreement with Floyd-Warshall    : ${agree}/${agree + disagree}`);
  say(`Disagreements                    : ${disagree}`);
  if (mismatches.length) say(`  ${JSON.stringify(mismatches)}`);

  // --- Multi-hop discovery -------------------------------------------------
  // The graph is deliberately sparse. These two journeys have no direct edge,
  // so a correct implementation must discover the intermediate stop.
  const accTak = calculateShortestPath('Acc', 'Tak');
  const accTam = calculateShortestPath('Acc', 'Tam');
  say('');
  say('Multi-hop route discovery (no direct edge exists for either):');
  say(`  Accra -> Takoradi : ${accTak.path.join(' -> ')}  = ${accTak.totalDistance} km, ${accTak.totalTimeMins} min`);
  say(`  Accra -> Tamale   : ${accTam.path.join(' -> ')}  = ${accTam.totalDistance} km, ${accTam.totalTimeMins} min`);

  // --- Unreachable-destination handling ------------------------------------
  const bogus = calculateShortestPath('Acc', 'ZZZ');
  const handlesUnreachable = Array.isArray(bogus.path) && bogus.path.length === 0 && bogus.totalDistance === 0;
  say(`  Unreachable destination returns empty path without throwing: ${handlesUnreachable}`);

  // --- Latency benchmark ---------------------------------------------------
  // Warm the JIT first, otherwise the first few hundred calls measure
  // compilation rather than the algorithm.
  for (let i = 0; i < 20000; i++) calculateShortestPath('Acc', 'Tam');

  const ITER = 200000;
  const samples = new Float64Array(1000);
  for (let s = 0; s < samples.length; s++) {
    const t0 = process.hrtime.bigint();
    calculateShortestPath('Acc', 'Tam');
    samples[s] = Number(process.hrtime.bigint() - t0) / 1000; // microseconds
  }
  const sorted = Array.from(samples).sort((a, b) => a - b);
  const median = sorted[Math.floor(sorted.length / 2)];
  const p95 = sorted[Math.floor(sorted.length * 0.95)];

  const tStart = process.hrtime.bigint();
  for (let i = 0; i < ITER; i++) calculateShortestPath('Acc', 'Tam');
  const totalNs = Number(process.hrtime.bigint() - tStart);
  const meanUs = totalNs / ITER / 1000;
  const opsPerSec = 1e9 / (totalNs / ITER);

  say('');
  say(`Latency, Accra -> Tamale (worst case: 3 nodes, ${ITER.toLocaleString()} iterations)`);
  say(`  mean          : ${f(meanUs, 3)} us`);
  say(`  median        : ${f(median, 3)} us`);
  say(`  95th pct      : ${f(p95, 3)} us`);
  say(`  throughput    : ${Math.round(opsPerSec).toLocaleString()} routes/second`);

  results.t1 = {
    pairsTested: agree + disagree,
    agreementWithReference: agree,
    disagreements: disagree,
    mismatches,
    handlesUnreachable,
    multiHop: {
      accraTakoradi: { path: accTak.path, km: accTak.totalDistance, mins: accTak.totalTimeMins },
      accraTamale: { path: accTam.path, km: accTam.totalDistance, mins: accTam.totalTimeMins }
    },
    latencyUs: { mean: meanUs, median, p95 },
    routesPerSecond: opsPerSec,
    iterations: ITER,
    pathTable
  };

  md.push('## T1. Route optimisation');
  md.push('');
  md.push(`Dijkstra's implementation was checked against an independently written Floyd-Warshall all-pairs reference. The two share no code.`);
  md.push('');
  md.push('| Metric | Result |');
  md.push('|---|---|');
  md.push(`| Node pairs tested | ${agree + disagree} |`);
  md.push(`| Agreement with reference | ${agree}/${agree + disagree} |`);
  md.push(`| Mean latency (Accra to Tamale) | ${f(meanUs, 3)} us |`);
  md.push(`| Median latency | ${f(median, 3)} us |`);
  md.push(`| 95th percentile latency | ${f(p95, 3)} us |`);
  md.push(`| Throughput | ${Math.round(opsPerSec).toLocaleString()} routes/second |`);
  md.push('');
  md.push('Selected multi-hop routes, neither of which has a direct edge in the graph:');
  md.push('');
  md.push('| Journey | Path discovered | Distance | Duration |');
  md.push('|---|---|---|---|');
  md.push(`| Accra to Takoradi | ${accTak.path.join(' to ')} | ${accTak.totalDistance} km | ${accTak.totalTimeMins} min |`);
  md.push(`| Accra to Tamale | ${accTam.path.join(' to ')} | ${accTam.totalDistance} km | ${accTam.totalTimeMins} min |`);
  md.push('');
}

// ===========================================================================
// T2 — DISPATCH MODEL: RESPONSE TO BOOKING VELOCITY
// ===========================================================================

function t2DispatchModel() {
  heading('T2  DISPATCH MODEL — RESPONSE TO BOOKING VELOCITY');

  // A 44-seat STC coach, the smaller of the two fleet types in the seed data.
  const TOTAL_SEATS = 44;
  const mkSchedule = (reserved) => ({
    id: 'sch-test', operatorId: 'op-stc', routeId: 'r-acc-kum',
    busNumber: 'STC-101-26', totalSeats: TOTAL_SEATS,
    reservedSeats: Array.from({ length: reserved }, (_, i) => i + 1),
    scheduledTime: '08:00', estimatedDepartureTime: '08:00',
    departureRatePerHour: 15, status: 'scheduled'
  });

  const threshold = Math.floor(TOTAL_SEATS * 0.85);
  say(`Bus capacity ${TOTAL_SEATS} seats; dispatch threshold ${threshold} seats (85%).`);
  say('');

  const velocities = [0, 5, 10, 15, 20, 30, 45, 60, 90, 120];
  const levels = [0, 10, 20, 30, 37];

  // Header row
  let header = 'fill'.padEnd(6) + '| ' + velocities.map(v => String(v).padStart(6)).join(' ');
  say('Estimated minutes to departure, by booking velocity (passengers/hour)');
  say(header);
  say('-'.repeat(header.length));

  const grid = [];
  for (const level of levels) {
    const row = { bucketLevel: level, congestionIndex: null, byVelocity: {} };
    const cells = [];
    for (const v of velocities) {
      const st = runLeakyBucketSimulation(mkSchedule(level), v);
      row.congestionIndex = st.congestionIndex;
      row.byVelocity[v] = st.estimatedMinutesToDeparture;
      cells.push(String(st.estimatedMinutesToDeparture).padStart(6));
    }
    grid.push(row);
    say(String(level).padEnd(6) + '| ' + cells.join(' '));
  }

  say('');
  say('Congestion index by fill level:');
  for (const r of grid) {
    say(`  ${String(r.bucketLevel).padStart(2)} seats booked -> ${f(r.congestionIndex * 100, 1)}%`);
  }

  // --- Model sanity properties ---------------------------------------------
  // A dispatch model whose projected wait does not fall as demand rises would
  // be modelling nothing useful. These assertions test the model's behaviour,
  // not merely that it returns a number.
  let monotonic = true;
  for (const r of grid) {
    if (r.bucketLevel >= threshold) continue; // already departing, always 0
    const positive = velocities.filter(v => v > 0);
    for (let i = 1; i < positive.length; i++) {
      if (r.byVelocity[positive[i]] > r.byVelocity[positive[i - 1]]) monotonic = false;
    }
  }

  const atThreshold = runLeakyBucketSimulation(mkSchedule(threshold), 15);
  const zeroVelocity = runLeakyBucketSimulation(mkSchedule(0), 0);
  const overfull = runLeakyBucketSimulation(mkSchedule(TOTAL_SEATS), 15);

  say('');
  say('Model properties:');
  say(`  Wait falls monotonically as velocity rises   : ${monotonic}`);
  say(`  At threshold (${threshold} seats) departs immediately : ${atThreshold.estimatedMinutesToDeparture === 0}`);
  say(`  Zero velocity yields finite fallback wait    : ${zeroVelocity.estimatedMinutesToDeparture === 120} (${zeroVelocity.estimatedMinutesToDeparture} min)`);
  say(`  Full bus never reports negative wait         : ${overfull.estimatedMinutesToDeparture >= 0}`);
  say(`  Congestion index bounded to 0..1             : ${overfull.congestionIndex <= 1}`);

  results.t2 = {
    totalSeats: TOTAL_SEATS,
    threshold,
    velocities,
    grid,
    properties: {
      monotonicInVelocity: monotonic,
      departsAtThreshold: atThreshold.estimatedMinutesToDeparture === 0,
      zeroVelocityFallbackMinutes: zeroVelocity.estimatedMinutesToDeparture,
      noNegativeWait: overfull.estimatedMinutesToDeparture >= 0,
      congestionBounded: overfull.congestionIndex <= 1
    }
  };

  md.push('## T2. Dispatch model');
  md.push('');
  md.push(`Bus capacity ${TOTAL_SEATS} seats, dispatch threshold ${threshold} seats (85% of capacity). Cells give projected minutes to departure.`);
  md.push('');
  md.push('| Seats booked | ' + velocities.map(v => `${v}/hr`).join(' | ') + ' |');
  md.push('|---|' + velocities.map(() => '---').join('|') + '|');
  for (const r of grid) {
    md.push(`| ${r.bucketLevel} | ` + velocities.map(v => r.byVelocity[v]).join(' | ') + ' |');
  }
  md.push('');
}

// ===========================================================================
// T3 — TICKET INTEGRITY
// ===========================================================================

function t3TicketIntegrity() {
  heading('T3  TICKET INTEGRITY — TAMPER DETECTION AND FORGERY');

  const names = ['Kwesi Mensah', 'Ama Serwaa', 'Kofi Owusu-Ansah', 'Adwoa Nyarko', 'Yaa Asantewaa', 'Kwabena Boateng'];
  const buses = ['VIP-843-26', 'STC-101-26', 'VIP-220-26', 'STC-457-26'];
  const mkTicket = (i) => {
    const ticketId = `TKT-${1000 + i}-GH`;
    const passengerName = names[i % names.length];
    const seatNumber = (i % 44) + 1;
    const busNumber = buses[i % buses.length];
    return {
      ticketId, passengerName, seatNumber, busNumber,
      signature: generateOfflineSignature(ticketId, passengerName, seatNumber, busNumber)
    };
  };

  const N = 5000;

  // --- Genuine tickets must all verify -------------------------------------
  let accepted = 0;
  for (let i = 0; i < N; i++) if (verifyOfflineTicket(mkTicket(i))) accepted++;

  // --- Tampering with each field must be detected --------------------------
  const tamperResults = {};
  for (const field of ['ticketId', 'passengerName', 'seatNumber', 'busNumber']) {
    let detected = 0;
    for (let i = 0; i < N; i++) {
      const t = mkTicket(i);
      // Alter one field while keeping the original signature, which is exactly
      // what an attacker editing a ticket would do.
      if (field === 'seatNumber') t[field] = t[field] === 44 ? 1 : t[field] + 1;
      else t[field] = t[field] + 'X';
      if (!verifyOfflineTicket(t)) detected++;
    }
    tamperResults[field] = { trials: N, detected, rate: detected / N };
  }

  // --- Forged signatures must be rejected ----------------------------------
  let forgedRejected = 0;
  for (let i = 0; i < N; i++) {
    const t = mkTicket(i);
    // A random 256-bit tag: an attacker guessing without the key.
    let fake = '';
    for (let k = 0; k < 64; k++) fake += '0123456789ABCDEF'[Math.floor(Math.random() * 16)];
    t.signature = fake;
    if (!verifyOfflineTicket(t)) forgedRejected++;
  }

  say(`Genuine tickets accepted            : ${accepted}/${N}`);
  for (const [field, r] of Object.entries(tamperResults)) {
    say(`Tampered ${field.padEnd(14)} detected : ${r.detected}/${r.trials}`);
  }
  say(`Forged signatures rejected          : ${forgedRejected}/${N}`);

  // --- Avalanche behaviour -------------------------------------------------
  // A one-character change should alter roughly half the output bits. This is
  // the standard empirical check on a hash's diffusion.
  const hexToBits = (hex) => {
    let bits = 0;
    for (let i = 0; i < hex.length; i++) {
      const v = parseInt(hex[i], 16);
      bits += (v & 1) + ((v >> 1) & 1) + ((v >> 2) & 1) + ((v >> 3) & 1);
    }
    return bits;
  };
  const hamming = (a, b) => {
    let d = 0;
    for (let i = 0; i < a.length; i++) {
      const x = parseInt(a[i], 16) ^ parseInt(b[i], 16);
      d += (x & 1) + ((x >> 1) & 1) + ((x >> 2) & 1) + ((x >> 3) & 1);
    }
    return d;
  };

  const AV = 2000;
  let sumDist = 0, minDist = 256, maxDist = 0;
  for (let i = 0; i < AV; i++) {
    const t = mkTicket(i);
    const a = t.signature;
    // Change exactly one character of the passenger name.
    const altered = generateOfflineSignature(t.ticketId, t.passengerName.slice(0, -1) + 'z', t.seatNumber, t.busNumber);
    const d = hamming(a, altered);
    sumDist += d;
    if (d < minDist) minDist = d;
    if (d > maxDist) maxDist = d;
  }
  const meanDist = sumDist / AV;

  say('');
  say(`Avalanche over ${AV} single-character changes (256-bit tag):`);
  say(`  mean bits changed : ${f(meanDist, 1)} (${f(meanDist / 256 * 100, 1)}%, ideal 50%)`);
  say(`  range             : ${minDist} to ${maxDist}`);

  // --- Collision resistance: the replaced scheme vs the current one --------
  // The superseded 32-bit djb2 construction is reimplemented here purely so
  // the two can be compared on identical input. This quantifies why it was
  // replaced.
  const djb2Legacy = (ticketId, name, seat, bus) => {
    const payload = `${ticketId}-${name}-${seat}-${bus}-GhanaTBSSecretKey2026`;
    let hash = 0;
    for (let i = 0; i < payload.length; i++) {
      hash = (hash << 5) - hash + payload.charCodeAt(i);
      hash = hash & hash;
    }
    return Math.abs(hash).toString(16).toUpperCase();
  };

  const M = 200000;
  const seenLegacy = new Set(), seenHmac = new Set();
  let legacyCollisions = 0, hmacCollisions = 0;
  for (let i = 0; i < M; i++) {
    const id = `TKT-${i}-GH`, nm = names[i % names.length], st = (i % 44) + 1, bs = buses[i % buses.length];
    const l = djb2Legacy(id, nm, st, bs);
    if (seenLegacy.has(l)) legacyCollisions++; else seenLegacy.add(l);
    const h = generateOfflineSignature(id, nm, st, bs);
    if (seenHmac.has(h)) hmacCollisions++; else seenHmac.add(h);
  }

  say('');
  say(`Collision search over ${M.toLocaleString()} distinct tickets:`);
  say(`  superseded djb2-32 scheme : ${legacyCollisions.toLocaleString()} collisions`);
  say(`  current HMAC-SHA256       : ${hmacCollisions.toLocaleString()} collisions`);

  results.t3 = {
    trials: N,
    genuineAccepted: accepted,
    tamperDetection: tamperResults,
    forgedRejected,
    avalanche: { trials: AV, meanBitsChanged: meanDist, percent: meanDist / 256 * 100, min: minDist, max: maxDist },
    collisions: { tickets: M, legacyDjb2: legacyCollisions, hmacSha256: hmacCollisions }
  };

  md.push('## T3. Ticket integrity');
  md.push('');
  md.push('| Test | Trials | Result |');
  md.push('|---|---|---|');
  md.push(`| Genuine tickets accepted | ${N} | ${accepted}/${N} |`);
  for (const [field, r] of Object.entries(tamperResults)) {
    md.push(`| Tampered \`${field}\` detected | ${r.trials} | ${r.detected}/${r.trials} |`);
  }
  md.push(`| Forged signatures rejected | ${N} | ${forgedRejected}/${N} |`);
  md.push(`| Avalanche, mean bits changed of 256 | ${AV} | ${f(meanDist, 1)} (${f(meanDist / 256 * 100, 1)}%) |`);
  md.push(`| Collisions, superseded djb2-32 | ${M.toLocaleString()} | ${legacyCollisions.toLocaleString()} |`);
  md.push(`| Collisions, HMAC-SHA256 | ${M.toLocaleString()} | ${hmacCollisions.toLocaleString()} |`);
  md.push('');
}

// ===========================================================================
// T4 — CONCURRENCY: THE SEAT RESERVATION WRITE PATH
// ===========================================================================
// This test reproduces the write pattern used by src/app/page.tsx: read the
// schedule's reservedSeats array into client state, append the chosen seat,
// then write the WHOLE array back with an unconditional UPDATE.
//
// The claim under test, stated in project_plan.md, is that Supabase's
// real-time replication "prevents database race conditions when multiple
// clients attempt to reserve the same seat simultaneously".

function t4Concurrency() {
  heading('T4  CONCURRENCY — SEAT RESERVATION UNDER SIMULTANEOUS BOOKING');

  say('Reproducing the read-modify-write pattern of src/app/page.tsx:196-252.');
  say('');

  /** A stand-in for the schedules row, holding the reserved_seats array. */
  class Row {
    constructor() { this.reservedSeats = []; this.writes = 0; }
    read() { return [...this.reservedSeats]; }               // SELECT
    write(arr) { this.reservedSeats = [...arr]; this.writes++; } // UPDATE ... SET reserved_seats = <array>
  }

  // --- Scenario A: two passengers book DIFFERENT seats ---------------------
  const TRIALS = 1000;
  let lostUpdates = 0;
  for (let t = 0; t < TRIALS; t++) {
    const row = new Row();
    // Both clients load the seat map before either commits: the interleaving
    // that occurs whenever two people browse the same bus at the same time.
    const clientA = row.read();
    const clientB = row.read();
    clientA.push(10);
    clientB.push(20);
    row.write(clientA);
    row.write(clientB); // B's write is based on stale state and erases seat 10
    if (!(row.reservedSeats.includes(10) && row.reservedSeats.includes(20))) lostUpdates++;
  }
  say(`Scenario A — two passengers, different seats (10 and 20), ${TRIALS} trials`);
  say(`  Trials where a confirmed reservation was silently erased : ${lostUpdates}/${TRIALS}`);
  const rowA = new Row();
  const a1 = rowA.read(); const a2 = rowA.read();
  a1.push(10); a2.push(20); rowA.write(a1); rowA.write(a2);
  say(`  Final stored array                                       : [${rowA.reservedSeats.join(', ')}]`);
  say(`  Seat 10 holds a valid signed ticket but no reservation.`);

  // --- Scenario B: two passengers book the SAME seat -----------------------
  let doubleSold = 0;
  for (let t = 0; t < TRIALS; t++) {
    const row = new Row();
    const clientA = row.read();
    const clientB = row.read();
    // Both clients check availability against the state they loaded. Neither
    // sees the other's pending selection, so both guards pass.
    const aFree = !clientA.includes(15);
    const bFree = !clientB.includes(15);
    if (aFree && bFree) {
      clientA.push(15); row.write(clientA);
      clientB.push(15); row.write(clientB);
      doubleSold++;
    }
  }
  say('');
  say(`Scenario B — two passengers, SAME seat (15), ${TRIALS} trials`);
  say(`  Trials where both passengers received a ticket for seat 15 : ${doubleSold}/${TRIALS}`);

  // --- Scenario C: the same workload under a compare-and-set write ---------
  // Demonstrates that the defect is in the write strategy, not inherent to the
  // problem. A conditional update rejects a write based on stale state.
  class GuardedRow extends Row {
    constructor() { super(); this.version = 0; }
    read() { return { seats: [...this.reservedSeats], version: this.version }; }
    /** Commits only if no other write has landed since the caller read. */
    write(seats, version) {
      if (version !== this.version) return false; // stale, caller must retry
      this.reservedSeats = [...seats];
      this.version++;
      return true;
    }
  }

  let guardedLost = 0, retries = 0;
  for (let t = 0; t < TRIALS; t++) {
    const row = new GuardedRow();
    const a = row.read(); const b = row.read();
    row.write([...a.seats, 10], a.version);
    if (!row.write([...b.seats, 20], b.version)) {
      // Rejected as stale. The client re-reads and retries, which is what a
      // correct implementation must do.
      retries++;
      const fresh = row.read();
      row.write([...fresh.seats, 20], fresh.version);
    }
    if (!(row.reservedSeats.includes(10) && row.reservedSeats.includes(20))) guardedLost++;
  }
  say('');
  say(`Scenario C — identical workload with a compare-and-set write, ${TRIALS} trials`);
  say(`  Stale writes correctly rejected and retried : ${retries}/${TRIALS}`);
  say(`  Reservations lost                           : ${guardedLost}/${TRIALS}`);

  say('');
  say('FINDING: the current write path does not prevent the race. Real-time');
  say('replication propagates changes to subscribers; it does not serialise');
  say('conflicting writes. Preventing the double sale requires a uniqueness');
  say('constraint or a conditional update at the database.');

  results.t4 = {
    trials: TRIALS,
    scenarioA_lostUpdates: lostUpdates,
    scenarioA_finalArray: rowA.reservedSeats,
    scenarioB_doubleSold: doubleSold,
    scenarioC_staleWritesRejected: retries,
    scenarioC_lostUpdates: guardedLost,
    liveSupabaseTested: false,
    note: 'Executed against an in-process reproduction of the write path. The hosted Supabase instance was not reachable from the evaluation environment, so the live two-client test remains to be run separately.'
  };

  md.push('## T4. Concurrency');
  md.push('');
  md.push('Reproduction of the read-modify-write reservation path used by the commuter portal.');
  md.push('');
  md.push('| Scenario | Trials | Outcome |');
  md.push('|---|---|---|');
  md.push(`| A. Different seats, current write path | ${TRIALS} | ${lostUpdates} reservations silently erased |`);
  md.push(`| B. Same seat, current write path | ${TRIALS} | ${doubleSold} double sales |`);
  md.push(`| C. Different seats, compare-and-set | ${TRIALS} | ${guardedLost} lost, ${retries} stale writes rejected and retried |`);
  md.push('');
}

// ===========================================================================
// T5 — DEGRADATION: BEHAVIOUR WITHOUT THE CLOUD DATABASE
// ===========================================================================

async function t5Degradation() {
  heading('T5  DEGRADATION — BEHAVIOUR WITHOUT THE CLOUD DATABASE');

  // Install the browser shims, then load the data layer. Order matters: the
  // module captures `typeof window` at load time.
  global.window = { localStorage: new MemoryStorage() };
  global.localStorage = global.window.localStorage;

  const db = require(path.join(BUILD, 'database.js'));

  const checks = {};
  let threw = null;

  try {
    const schedules = await db.getSchedules();
    checks.schedulesReturned = schedules.length;
    checks.selfSeeded = schedules.length > 0;

    // Expected seed size: routes x operators x 6 departure slots.
    checks.expectedSeedSize = db.ROUTES.length * db.OPERATORS.length * 6;
    checks.seedSizeMatches = schedules.length === checks.expectedSeedSize;

    // Write a booking through the fallback tier and read it back.
    const ticketId = 'TKT-EVAL-001';
    const sig = generateOfflineSignature(ticketId, 'Evaluation Passenger', 7, 'STC-101-26');
    await db.addBooking({
      id: ticketId, scheduleId: schedules[0].id,
      passengerName: 'Evaluation Passenger', passengerPhone: '0240000000',
      seatNumber: 7, momoProvider: 'MTN', momoTransactionId: 'SIM-EVAL-1',
      amountPaid: 120, timestamp: new Date().toISOString(),
      qrPayload: JSON.stringify({ ticketId, signature: sig }),
      isValidated: false
    });
    const bookings = await db.getBookings();
    checks.bookingPersisted = bookings.some(b => b.id === ticketId);

    // The persisted ticket must still verify offline after the round trip.
    const stored = bookings.find(b => b.id === ticketId);
    const payload = JSON.parse(stored.qrPayload);
    checks.signatureSurvivesRoundTrip = payload.signature === sig;

    // Persist a schedule change through the fallback tier.
    const target = { ...schedules[0], reservedSeats: [7] };
    await db.saveSchedule(target);
    const reread = await db.getSchedules();
    checks.schedulePersisted = reread.find(s => s.id === target.id).reservedSeats.includes(7);

    // The audit ledger must also degrade rather than fail.
    await db.addAuditLog('operator', 'evaluation_entry', 'written during degradation test');
    const logs = await db.getAuditLogs();
    checks.auditLogWritten = logs.some(l => l.action === 'evaluation_entry');
  } catch (e) {
    threw = e && e.message ? e.message : String(e);
  }

  say(`Supabase client constructed         : ${false} (credentials absent)`);
  say(`Exception thrown during degradation : ${threw === null ? 'none' : threw}`);
  say(`Timetable self-seeded               : ${checks.selfSeeded} (${checks.schedulesReturned} buses)`);
  say(`Seed size matches routes x ops x 6  : ${checks.seedSizeMatches} (expected ${checks.expectedSeedSize})`);
  say(`Booking written and read back       : ${checks.bookingPersisted}`);
  say(`Ticket signature survives round trip: ${checks.signatureSurvivesRoundTrip}`);
  say(`Schedule change persisted           : ${checks.schedulePersisted}`);
  say(`Audit ledger entry written          : ${checks.auditLogWritten}`);

  results.t5 = { threw, ...checks };

  md.push('## T5. Degradation without the cloud database');
  md.push('');
  md.push('| Check | Result |');
  md.push('|---|---|');
  md.push(`| Exception thrown | ${threw === null ? 'none' : threw} |`);
  md.push(`| Timetable self-seeded | ${checks.selfSeeded} (${checks.schedulesReturned} buses) |`);
  md.push(`| Booking written and read back | ${checks.bookingPersisted} |`);
  md.push(`| Ticket signature survives round trip | ${checks.signatureSurvivesRoundTrip} |`);
  md.push(`| Schedule change persisted | ${checks.schedulePersisted} |`);
  md.push(`| Audit ledger entry written | ${checks.auditLogWritten} |`);
  md.push('');
}

